1	package api
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"net/http"
9		"net/url"
10		"strings"
11	
12		"github.com/gin-gonic/gin"
13	
14		"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
15	)
16	
17	// Error codes published by the service contract in README.md.
18	const (
19		codeInvalidInput = "InvalidNetPolicyInputError"
20		codeConflict     = "NetPolicyConflictError"
21		codeNotFound     = "NetPolicyNotFoundError"
22		codeStorage      = "storage_unavailable"
23	)
24	
25	// NewRouter wires the public HTTP surface. The service contract in README.md
26	// describes the error shape every entry must keep.
27	func NewRouter(st *store.Store) *gin.Engine {
28		gin.SetMode(gin.ReleaseMode)
29		router := gin.New()
30		router.Use(gin.Recovery())
31	
32		router.GET("/healthz", func(c *gin.Context) {
33			if err := st.Ping(); err != nil {
34				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
35				return
36			}
37			c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
38		})
39	
40		router.POST("/v1/net-policies", func(c *gin.Context) {
41			rec, ok := decodeNetPolicy(c.Request.Body)
42			if !ok {
43				writeError(c, http.StatusBadRequest, codeInvalidInput, "request body is not a valid net policy")
44				return
45			}
46			stored, created, err := st.Register(rec)
47			if errors.Is(err, store.ErrConflict) {
48				writeError(c, http.StatusConflict, codeConflict, "a different net policy already exists for this namespace and name")
49				return
50			}
51			if err != nil {
52				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
53				return
54			}
55			status := http.StatusOK
56			if created {
57				status = http.StatusCreated
58			}
59			c.JSON(status, stored)
60		})
61	
62		router.GET("/v1/net-policies", func(c *gin.Context) {
63			namespace, label, ok := parseNetPolicyQuery(c.Request.URL.RawQuery)
64			if !ok {
65				writeError(c, http.StatusBadRequest, codeInvalidInput, "query must be well-formed and carry a single non-blank namespace or label")
66				return
67			}
68			records, err := st.List(namespace, label)
69			if err != nil {
70				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
71				return
72			}
73			if len(records) == 0 {
74				writeError(c, http.StatusNotFound, codeNotFound, "no net policies match the query")
75				return
76			}
77			c.JSON(http.StatusOK, gin.H{"items": records})
78		})
79	
80		router.NoRoute(func(c *gin.Context) {
81			writeError(c, http.StatusNotFound, "route_not_found", "no route matches this path")
82		})
83		return router
84	}
85	
86	func writeError(c *gin.Context, status int, code, message string) {
87		c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
88	}
89	
90	// parseNetPolicyQuery strictly parses the raw query string for the GET entry.
91	// The whole query must validate before any record is returned: every segment
92	// needs valid percent escapes in both name and value, and no segment may carry
93	// an unescaped semicolon — a malformed fragment rejects the request even when
94	// it belongs to an unknown parameter or the remaining conditions would have
95	// matched committed records. Empty segments (including a trailing &) are
96	// skipped. Names are compared after a single decode, so "namespace" and
97	// "%6Eamespace" are the same parameter; a known parameter may appear at most
98	// once with a non-blank value, and at least one of namespace/label must be
99	// present. Legal unknown parameters are ignored. Values are decoded exactly
100	// once (+ means space) and matched verbatim — no trimming or case folding.
101	func parseNetPolicyQuery(rawQuery string) (namespace, label string, ok bool) {
102		seen := map[string]bool{}
103		values := map[string]string{}
104		for _, segment := range strings.Split(rawQuery, "&") {
105			if segment == "" {
106				continue
107			}
108			if strings.Contains(segment, ";") {
109				return "", "", false
110			}
111			name, value, _ := strings.Cut(segment, "=")
112			decodedName, err := url.QueryUnescape(name)
113			if err != nil {
114				return "", "", false
115			}
116			decodedValue, err := url.QueryUnescape(value)
117			if err != nil {
118				return "", "", false
119			}
120			if decodedName != "namespace" && decodedName != "label" {
121				continue
122			}
123			if seen[decodedName] || strings.TrimSpace(decodedValue) == "" {
124				return "", "", false
125			}
126			seen[decodedName] = true
127			values[decodedName] = decodedValue
128		}
129		namespace, label = values["namespace"], values["label"]
130		if namespace == "" && label == "" {
131			return "", "", false
132		}
133		return namespace, label, true
134	}
135	
136	// decodeNetPolicy strictly validates the request body: a single JSON object
137	// with the required fields, enums, and port intervals from the service contract.
138	//
139	// The top-level object is walked with a streaming decoder instead of a plain
140	// map decode so every occurrence of pluginParams is validated on its own: a
141	// later object must not overwrite an earlier illegal one before that earlier
142	// object is checked, so {"mode":null} followed by {"mode":"enforce"} fails.
143	// Field names match after JSON unescaping, making "pluginParams" and
144	// "\u0070luginParams" the same field. When every occurrence is legal the last
145	// complete object wins. Other fields keep their existing single-value
146	// parsing behaviour (a repeated name keeps its last value).
147	func decodeNetPolicy(body io.Reader) (store.Record, bool) {
148		decoder := json.NewDecoder(body)
149		opening, err := decoder.Token()
150		if err != nil {
151			return store.Record{}, false
152		}
153		if delim, ok := opening.(json.Delim); !ok || delim != '{' {
154			// Rejects empty input, null, scalars and arrays outright.
155			return store.Record{}, false
156		}
157	
158		raw := map[string]json.RawMessage{}
159		var (
160			pluginParams    map[string]string
161			pluginParamsSet bool
162		)
163		for decoder.More() {
164			keyToken, err := decoder.Token()
165			if err != nil {
166				return store.Record{}, false
167			}
168			key, ok := keyToken.(string)
169			if !ok {
170				return store.Record{}, false
171			}
172			var blob json.RawMessage
173			if err := decoder.Decode(&blob); err != nil {
174				return store.Record{}, false
175			}
176			if key == "pluginParams" {
177				// Validate each occurrence immediately: an illegal object must be
178				// rejected even when a later legal object would overwrite it.
179				params, valid := decodePluginObject(blob)
180				if !valid {
181					return store.Record{}, false
182				}
183				pluginParams, pluginParamsSet = params, true
184			}
185			raw[key] = blob
186		}
187		closing, err := decoder.Token()
188		if err != nil {
189			return store.Record{}, false
190		}
191		if delim, ok := closing.(json.Delim); !ok || delim != '}' {
192			return store.Record{}, false
193		}
194		var trailing any
195		if err := decoder.Decode(&trailing); err != io.EOF {
196			return store.Record{}, false
197		}
198	
199		var rec store.Record
200		var ok bool
201		if rec.Namespace, ok = requiredString(raw, "namespace"); !ok {
202			return store.Record{}, false
203		}
204		if rec.Name, ok = requiredString(raw, "name"); !ok {
205			return store.Record{}, false
206		}
207		if rec.Label, ok = requiredString(raw, "label"); !ok {
208			return store.Record{}, false
209		}
210		if rec.Rules, ok = decodeRules(raw); !ok {
211			return store.Record{}, false
212		}
213		if !pluginParamsSet {
214			return store.Record{}, false
215		}
216		rec.PluginParams = pluginParams
217		return rec, true
218	}
219	
220	// requiredString reads a present, non-blank JSON string field.
221	func requiredString(raw map[string]json.RawMessage, key string) (string, bool) {
222		blob, present := raw[key]
223		if !present {
224			return "", false
225		}
226		var value string
227		if err := json.Unmarshal(blob, &value); err != nil {
228			return "", false
229		}
230		if strings.TrimSpace(value) == "" {
231			return "", false
232		}
233		return value, true
234	}
235	
236	func decodeRules(raw map[string]json.RawMessage) ([]store.Rule, bool) {
237		blob, present := raw["rules"]
238		if !present {
239			return nil, false
240		}
241		var items []json.RawMessage
242		if err := json.Unmarshal(blob, &items); err != nil || len(items) == 0 {
243			return nil, false
244		}
245		rules := make([]store.Rule, 0, len(items))
246		for _, item := range items {
247			var fields map[string]json.RawMessage
248			if err := json.Unmarshal(item, &fields); err != nil {
249				return nil, false
250			}
251			direction, ok := requiredEnum(fields, "direction", "ingress", "egress")
252			if !ok {
253				return nil, false
254			}
255			action, ok := requiredEnum(fields, "action", "allow", "deny")
256			if !ok {
257				return nil, false
258			}
259			portsBlob, present := fields["ports"]
260			if !present {
261				return nil, false
262			}
263			var ports []int
264			if err := json.Unmarshal(portsBlob, &ports); err != nil || len(ports) != 2 {
265				return nil, false
266			}
267			if ports[0] < 1 || ports[0] > 65535 || ports[1] < 1 || ports[1] > 65535 || ports[0] > ports[1] {
268				return nil, false
269			}
270			rules = append(rules, store.Rule{Direction: direction, Action: action, Ports: [2]int{ports[0], ports[1]}})
271		}
272		return rules, true
273	}
274	
275	// requiredEnum reads a present JSON string field restricted to the given values.
276	func requiredEnum(raw map[string]json.RawMessage, key string, allowed ...string) (string, bool) {
277		blob, present := raw[key]
278		if !present {
279			return "", false
280		}
281		var value string
282		if err := json.Unmarshal(blob, &value); err != nil {
283			return "", false
284		}
285		for _, candidate := range allowed {
286			if value == candidate {
287				return value, true
288			}
289		}
290		return "", false
291	}
292	
293	// decodePluginObject validates and decodes one pluginParams value. The
294	// published contract is a string-to-string object: null, numbers, booleans,
295	// arrays and nested objects are invalid input rather than coerced or dropped.
296	//
297	// Members are walked with a streaming decoder so every occurrence of a repeated
298	// member name is inspected, not just the value a map decode would keep last.
299	// {"mode":null,"mode":"enforce"} must fail on the null even though a legal
300	// string follows it; keys are matched after JSON unescaping, so "mode" and
301	// "\u006dode" are the same member. When every occurrence is a string the last
302	// value for each decoded key wins, and the empty object yields an empty map.
303	func decodePluginObject(blob json.RawMessage) (map[string]string, bool) {
304		decoder := json.NewDecoder(bytes.NewReader(blob))
305		opening, err := decoder.Token()
306		if err != nil {
307			return nil, false
308		}
309		delim, ok := opening.(json.Delim)
310		if !ok || delim != '{' {
311			// Rejects null, scalars and arrays outright.
312			return nil, false
313		}
314	
315		params := map[string]string{}
